define([],(function(){return class MoodleScroll{init(){return this.scrollY=0,window.addEventListener("scroll",this.scrollHandler.bind(this)),this}getScrollPosition(){return window.pageYOffset||document.documentElement.scrollTop}scrollHandler(){const e=document.querySelector("body");this.getScrollPosition()>=window.innerHeight?e.classList.add("scrolled"):e.classList.remove("scrolled")}}}));